static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int* sortGrades(int* grades, int gradesSize, int* returnSize) {
    int* a = malloc(gradesSize * sizeof(int));
    memcpy(a, grades, gradesSize * sizeof(int));
    qsort(a, gradesSize, sizeof(int), cmp_int);
    *returnSize = gradesSize;
    return a;
}

