class Solution:
    def sortGrades(self, grades: List[int]) -> List[int]:
        count = [0] * 101
        for g in grades:
            count[g] += 1
        out = []
        for g in range(101):
            out.extend([g] * count[g])
        return out

code.java:
class Solution {
    public int[] sortGrades(int[] grades) {
        int[] count = new int[101];
        for (int g : grades) count[g]++;
        int[] out = new int[grades.length];
        int w = 0;
        for (int g = 0; g <= 100; g++)
            for (int c = 0; c < count[g]; c++) out[w++] = g;
        return out;
    }
}

