    vector<int> sortGrades(vector<int>& grades) {
        int count[101] = {0};
        for (int g : grades) count[g]++;
        vector<int> out;
        for (int g = 0; g <= 100; g++) out.insert(out.end(), count[g], g);
        return out;
    }
};

