int* sortGrades(int* grades, int gradesSize, int* returnSize) {
    int count[101] = {0};
    for (int i = 0; i < gradesSize; i++) count[grades[i]]++;
    int* out = malloc(gradesSize * sizeof(int));
    int w = 0;
    for (int g = 0; g <= 100; g++)
        for (int c = 0; c < count[g]; c++) out[w++] = g;
    *returnSize = gradesSize;
    return out;
}
